(function () {
"use strict";
var toggle = document.querySelector(".nav-toggle");
var nav = document.getElementById("primary-nav");
if (toggle && nav) {
var setOpen = function (open) {
nav.classList.toggle("is-open", open);
toggle.setAttribute("aria-expanded", open ? "true" : "false");
toggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
};
toggle.addEventListener("click", function () {
setOpen(!nav.classList.contains("is-open"));
});
document.addEventListener("keydown", function (e) {
if (e.key === "Escape" && nav.classList.contains("is-open")) {
setOpen(false);
toggle.focus();
}
});
nav.addEventListener("click", function (e) {
if (e.target.closest("a") && nav.classList.contains("is-open")) {
setOpen(false);
}
});
var mq = window.matchMedia("(min-width: 1001px)");
var onChange = function (e) {
if (e.matches) {
setOpen(false);
}
};
if (mq.addEventListener) {
mq.addEventListener("change", onChange);
} else if (mq.addListener) {
mq.addListener(onChange);
}
}
var UTM = "?utm_source=website&utm_medium=organic&utm_campaign=eds_site";
document.querySelectorAll('a[href^="https://phorest.com/book/"]').forEach(function (a) {
if (a.href.indexOf("utm_source") === -1) {
a.href = a.href + UTM;
}
});
var year = document.querySelector("[data-year]");
if (year) {
year.textContent = String(new Date().getFullYear());
}
})();